CREATE EXTENSION IF NOT EXISTS pgcrypto;

DROP TABLE IF EXISTS ticket_history CASCADE;
DROP TABLE IF EXISTS ticket_comments CASCADE;
DROP TABLE IF EXISTS tickets CASCADE;
DROP TABLE IF EXISTS asset_assignments CASCADE;
DROP TABLE IF EXISTS assets CASCADE;
DROP TABLE IF EXISTS employee_privileges CASCADE;
DROP TABLE IF EXISTS special_privileges CASCADE;
DROP TABLE IF EXISTS employee_qualifications CASCADE;
DROP TABLE IF EXISTS role_pages CASCADE;
DROP TABLE IF EXISTS pages CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS roles CASCADE;
DROP TABLE IF EXISTS employees CASCADE;
DROP TABLE IF EXISTS departments CASCADE;

CREATE TABLE departments (id BIGSERIAL PRIMARY KEY, department_name VARCHAR(100) NOT NULL UNIQUE, status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE employees (id BIGSERIAL PRIMARY KEY, employee_code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, dob DATE, email VARCHAR(160) NOT NULL UNIQUE, phone VARCHAR(30), secondary_phone VARCHAR(30), qualification VARCHAR(160), address_line VARCHAR(255), city VARCHAR(100), post VARCHAR(100), state VARCHAR(100), pin_code VARCHAR(20), department_id BIGINT, designation VARCHAR(100), joining_date DATE, manager_id BIGINT, image_url VARCHAR(255), status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL, FOREIGN KEY (manager_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE assets (id BIGSERIAL PRIMARY KEY, asset_name VARCHAR(160) NOT NULL, serial_no VARCHAR(120) NOT NULL UNIQUE, asset_type VARCHAR(30) NOT NULL, make VARCHAR(120), model VARCHAR(120), year_of_purchase INTEGER, purchased_from VARCHAR(180), price DECIMAL(12,2), status VARCHAR(10) NOT NULL DEFAULT 'AVAILABLE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employee_qualifications (id BIGSERIAL PRIMARY KEY, employee_id BIGINT NOT NULL, course_degree VARCHAR(160) NOT NULL, institute_name VARCHAR(180) NOT NULL, year_passed INTEGER NOT NULL, percentage DECIMAL(5,2), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE special_privileges (id BIGSERIAL PRIMARY KEY, privilege_key VARCHAR(80) NOT NULL UNIQUE, privilege_name VARCHAR(120) NOT NULL UNIQUE, sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE employee_privileges (employee_id BIGINT NOT NULL, privilege_id BIGINT NOT NULL, granted BOOLEAN NOT NULL DEFAULT TRUE, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (employee_id, privilege_id), FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY (privilege_id) REFERENCES special_privileges(id) ON DELETE CASCADE);
CREATE TABLE roles (id BIGSERIAL PRIMARY KEY, role_name VARCHAR(80) NOT NULL UNIQUE, status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pages (id BIGSERIAL PRIMARY KEY, page_key VARCHAR(80) NOT NULL UNIQUE, page_name VARCHAR(120) NOT NULL, page_group VARCHAR(80) NOT NULL, sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE role_pages (role_id BIGINT NOT NULL, page_id BIGINT NOT NULL, PRIMARY KEY (role_id, page_id), FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY (page_id) REFERENCES pages(id) ON DELETE CASCADE);
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash CHAR(64) NOT NULL, role VARCHAR(80) NOT NULL DEFAULT 'EMPLOYEE', role_id BIGINT, employee_id BIGINT, status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE SET NULL, FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE asset_assignments (id BIGSERIAL PRIMARY KEY, asset_id BIGINT NOT NULL, employee_id BIGINT NOT NULL, assigned_from DATE NOT NULL, assigned_to DATE, assigned_by BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (asset_id) REFERENCES assets(id) ON DELETE CASCADE, FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY (assigned_by) REFERENCES users(id));
CREATE TABLE tickets (id BIGSERIAL PRIMARY KEY, ticket_number VARCHAR(30) NOT NULL UNIQUE, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, created_by BIGINT NOT NULL, assigned_to BIGINT, department_id BIGINT, asset_id BIGINT, priority VARCHAR(10) NOT NULL DEFAULT 'MEDIUM', status VARCHAR(15) NOT NULL DEFAULT 'NEW', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, due_date DATE, resolved_at TIMESTAMP, closed_at TIMESTAMP, FOREIGN KEY (created_by) REFERENCES employees(id), FOREIGN KEY (assigned_to) REFERENCES employees(id) ON DELETE SET NULL, FOREIGN KEY (department_id) REFERENCES departments(id) ON DELETE SET NULL, FOREIGN KEY (asset_id) REFERENCES assets(id) ON DELETE SET NULL);
CREATE TABLE ticket_comments (id BIGSERIAL PRIMARY KEY, ticket_id BIGINT NOT NULL, user_id BIGINT NOT NULL, comment TEXT NOT NULL, note_flag VARCHAR(10) NOT NULL DEFAULT 'MESSAGE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE ticket_history (id BIGSERIAL PRIMARY KEY, ticket_id BIGINT NOT NULL, user_id BIGINT NOT NULL, event_type VARCHAR(10) NOT NULL DEFAULT 'STATUS', old_status VARCHAR(30), new_status VARCHAR(30), assigned_to BIGINT, remarks VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (ticket_id) REFERENCES tickets(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (assigned_to) REFERENCES employees(id) ON DELETE SET NULL);

